import type { Question } from "@/lib/questionBank";

// Sexual Reproduction in Flowering Plants - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'
// Note: ~200 questions total, with an increased number of questions across every non-mcq type.

const questions: Question[] = [

  // ============ FLOWER: A RECAP / PRE-FERTILISATION OVERVIEW ============
  { id: 'srfp-1', type: 'mcq', question: 'In flowering plants, sexual reproduction involves which two essential events occurring in the flower?', options: ['Formation of pollen only', 'Formation of male and female gametes and their fusion', 'Germination of seed and growth of seedling', 'Formation of fruit and seed only'], correctIndex: 1, explanation: 'The flower is the reproductive part of angiosperms, where the male and female gametes are formed and fertilisation (fusion of gametes) occurs.', difficulty: 'easy' },
  { id: 'srfp-2', type: 'mcq', question: 'The male reproductive organ of a flower, consisting of a filament and an anther, is the:', options: ['Stamen', 'Sepal', 'Petal', 'Pistil'], correctIndex: 0, explanation: 'The stamen is the male reproductive part of the flower; it typically bears a stalk (filament) and a terminal anther.', difficulty: 'easy' },
  { id: 'srfp-3', type: 'mcq', question: 'The female reproductive organ of a flower, made up of ovary, style and stigma, is called the:', options: ['Calyx', 'Pistil (carpel)', 'Corolla', 'Stamen'], correctIndex: 1, explanation: 'The pistil (or carpel) is the female reproductive part; it consists of the ovary (basal), style (middle) and stigma (terminal, receptive to pollen).', difficulty: 'easy' },
  { id: 'srfp-4', type: 'mcq', question: 'Events occurring before fertilisation in flowering plants, such as gametogenesis and pollination, are grouped under:', options: ['Fertilisation events', 'Post-fertilisation events', 'Germination events', 'Pre-fertilisation events'], correctIndex: 3, explanation: 'Pre-fertilisation events include gametogenesis (formation of male and female gametes) and pollination.', difficulty: 'easy' },
  { id: 'srfp-5', type: 'mcq', question: 'The process by which haploid gametes are formed within the flower is called:', options: ['Pollination', 'Fertilisation', 'Germination', 'Gametogenesis'], correctIndex: 3, explanation: 'Gametogenesis is the process of formation of male and female gametes, occurring in the anther and ovule respectively.', difficulty: 'easy' },

  // ============ STAMEN, MICROSPORANGIUM & ANTHER STRUCTURE ============
  { id: 'srfp-6', type: 'mcq', question: 'A typical, fertile anther is generally:', options: ['Bilobed and dithecous, with each lobe having two theca', 'Tetralobed but monosporangiate', 'Unilobed and bisporangiate', 'Absent of any lobing pattern'], correctIndex: 0, explanation: 'A typical anther is bilobed, and each lobe (theca) is dithecous, i.e., each theca has two microsporangia, making four microsporangia in total per anther.', difficulty: 'medium' },
  { id: 'srfp-7', type: 'mcq', question: 'The total number of microsporangia typically present in a bilobed, dithecous anther is:', options: ['Six', 'Eight', 'Four', 'Two'], correctIndex: 2, explanation: 'A typical dithecous anther has two lobes, each with two microsporangia (pollen sacs), giving a total of four microsporangia.', difficulty: 'medium' },
  { id: 'srfp-8', type: 'mcq', question: 'The microsporangia present in the anther ultimately develop into:', options: ['Integuments', 'Ovules', 'Nucellus', 'Pollen sacs containing pollen grains'], correctIndex: 3, explanation: 'Each microsporangium develops into a pollen sac, which contains pollen grains (male gametophytes) at maturity.', difficulty: 'easy' },
  { id: 'srfp-9', type: 'mcq', question: 'A transverse section of a young anther shows the microsporangium surrounded, from outside to inside, by which sequence of wall layers?', options: ['Endothecium, epidermis, tapetum, middle layers', 'Epidermis, tapetum, endothecium, middle layers', 'Epidermis, endothecium, middle layers, tapetum', 'Tapetum, middle layers, endothecium, epidermis'], correctIndex: 2, explanation: 'From outside to inside, the microsporangium wall has four layers: epidermis, endothecium, middle layers (2–3 layered) and the innermost tapetum.', difficulty: 'medium' },
  { id: 'srfp-10', type: 'mcq', question: 'The innermost wall layer of the microsporangium, which nourishes the developing pollen grains, is called the:', options: ['Endothecium', 'Epidermis', 'Middle layer', 'Tapetum'], correctIndex: 3, explanation: 'The tapetum is the innermost layer of the microsporangium wall; its cells possess dense cytoplasm and usually more than one nucleus, and it nourishes the developing pollen.', difficulty: 'easy' },
  { id: 'srfp-11', type: 'mcq', question: 'The outer three wall layers of the microsporangium (epidermis, endothecium and middle layers) mainly function for:', options: ['Formation of the megaspore mother cell', 'Protection and dehiscence of the mature anther', 'Nourishment of developing pollen grains', 'Formation of the pollen tube'], correctIndex: 1, explanation: 'The outer three wall layers primarily serve a protective function and help in dehiscence of the anther to release pollen grains.', difficulty: 'medium' },
  { id: 'srfp-12', type: 'mcq', question: 'The tapetal cells of the microsporangium are characterised by having:', options: ['No cytoplasm at all', 'A single, small nucleus and sparse cytoplasm', 'Thick, lignified cell walls', 'Dense cytoplasm and more than one nucleus'], correctIndex: 3, explanation: 'Tapetal cells possess dense cytoplasm and usually more than one nucleus, consistent with their role in nourishing developing pollen grains.', difficulty: 'medium' },
  { id: 'srfp-13', type: 'mcq', question: 'The mass of homogeneous cells occupying the centre of each microsporangium in a very young anther, from which pollen grains are ultimately produced, is called the:', options: ['Tapetum', 'Endothecium', 'Nucellus', 'Sporogenous tissue'], correctIndex: 3, explanation: 'In a young anther, each microsporangium contains a compact mass of homogeneous cells called sporogenous tissue, which gives rise to pollen mother cells.', difficulty: 'medium' },
  { id: 'srfp-14', type: 'assertion-reason', question: 'Assertion (A): The tapetum plays a critical nutritive role for the developing pollen grains within the microsporangium.\nReason (R): Tapetal cells possess dense cytoplasm and often multiple nuclei, providing them with the metabolic capacity to supply nutrients to the developing microspores.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The dense cytoplasm and multiple nuclei of tapetal cells correctly explain their capacity to nourish the developing pollen, supporting the assertion.', difficulty: 'medium' },
  { id: 'srfp-15', type: 'how-many', question: 'Consider the following statements about anther structure:\n1. A typical anther is bilobed and dithecous.\n2. Each theca of the anther contains a single microsporangium.\n3. The tapetum is the outermost wall layer of the microsporangium.\n4. Sporogenous tissue occupies the centre of each microsporangium in a young anther.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 4 are correct. Statement 2 is wrong (each theca has two microsporangia, not one), and statement 3 is wrong (tapetum is the innermost, not outermost, layer).', difficulty: 'medium' },

  // ============ MICROSPOROGENESIS ============
  { id: 'srfp-16', type: 'mcq', question: 'Cells of the sporogenous tissue that function directly as pollen (microspore) mother cells are:', options: ['Triploid', 'Haploid', 'Polyploid, always', 'Diploid'], correctIndex: 3, explanation: 'Microspore (pollen) mother cells (PMCs) are diploid cells of the sporogenous tissue.', difficulty: 'easy' },
  { id: 'srfp-17', type: 'mcq', question: 'The process by which microspores are formed from a pollen mother cell through meiosis is termed:', options: ['Embryogenesis', 'Microsporogenesis', 'Megasporogenesis', 'Gametogenesis'], correctIndex: 1, explanation: 'Microsporogenesis is the process of formation of microspores from a pollen mother cell (PMC) through meiosis.', difficulty: 'easy' },
  { id: 'srfp-18', type: 'mcq', question: 'Each microspore mother cell undergoing meiosis produces:', options: ['Eight microspores', 'A microspore tetrad of four microspores', 'A single microspore', 'Two microspores'], correctIndex: 1, explanation: 'Since meiosis is involved, a microspore mother cell divides to produce four haploid microspores, arranged as a microspore tetrad.', difficulty: 'easy' },
  { id: 'srfp-19', type: 'mcq', question: 'As the anther matures and dehydrates, the microspores of a tetrad, which are initially held together, typically:', options: ['Remain fused permanently as a single unit', 'Fuse with adjacent tetrads', 'Are digested by the tapetum', 'Dissociate from each other and develop into individual pollen grains'], correctIndex: 3, explanation: 'As anthers mature and dehydrate, microspores dissociate from each other, and each develops into a mature pollen grain.', difficulty: 'medium' },
  { id: 'srfp-20', type: 'mcq', question: 'Microsporogenesis in most angiosperms occurs during which stage of anther/flower development?', options: ['Only during germination', 'During the development of the flower bud, before pollen release', 'Only after fruit set', 'Only after seed formation'], correctIndex: 1, explanation: 'Microsporogenesis occurs during the development of the flower bud, well before pollen grains are shed at anthesis.', difficulty: 'medium' },
  { id: 'srfp-21', type: 'assertion-reason', question: 'Assertion (A): Microsporogenesis involves meiotic (reductional) division of the pollen mother cell.\nReason (R): Since pollen grains represent the first cell of the haploid male gametophyte generation, a reduction division is necessary to halve the chromosome number from the diploid sporophytic pollen mother cell.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The need to produce haploid microspores from a diploid mother cell correctly explains why meiosis (reduction division) occurs during microsporogenesis.', difficulty: 'medium' },
  { id: 'srfp-22', type: 'how-many', question: 'Consider the following statements about microsporogenesis:\n1. Pollen mother cells are diploid.\n2. Microsporogenesis involves mitotic division only.\n3. Each pollen mother cell produces four haploid microspores.\n4. Microspores of a tetrad always remain permanently fused together.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (microsporogenesis involves meiosis, not just mitosis), and statement 4 is wrong (microspores eventually dissociate from the tetrad).', difficulty: 'medium' },

  // ============ POLLEN GRAIN: STRUCTURE ============
  { id: 'srfp-24', type: 'mcq', question: 'The pollen grain represents the:', options: ['Male sporophyte', 'Male gametophyte', 'Female gametophyte', 'Zygote'], correctIndex: 1, explanation: 'The pollen grain is the male gametophyte of flowering plants, developing from the haploid microspore.', difficulty: 'easy' },
  { id: 'srfp-25', type: 'mcq', question: 'Pollen grains are generally spherical in shape and typically measure about:', options: ['1–2 millimetres in diameter', '250–500 micrometres in diameter', '1–5 micrometres in diameter', '25–50 micrometres in diameter'], correctIndex: 3, explanation: 'Pollen grains are usually spherical, with a diameter around 25–50 micrometres.', difficulty: 'medium' },
  { id: 'srfp-26', type: 'mcq', question: 'A mature pollen grain has a two-layered wall; the hard, outer layer is called the:', options: ['Intine', 'Exine', 'Tapetum', 'Testa'], correctIndex: 1, explanation: 'The pollen wall has two layers: the hard outer exine and the thin, continuous inner layer called intine.', difficulty: 'easy' },
  { id: 'srfp-27', type: 'mcq', question: 'The exine of the pollen grain is made up of a highly resistant substance called:', options: ['Suberin', 'Lignin', 'Cellulose', 'Sporopollenin'], correctIndex: 3, explanation: 'Exine is made of sporopollenin, one of the most resistant organic materials known.', difficulty: 'easy' },
  { id: 'srfp-28', type: 'mcq', question: 'Sporopollenin, the material of the pollen exine, is remarkably resistant because:', options: ['It dissolves easily in mild acids', 'No enzyme is currently known that can degrade it', 'It is highly soluble in water', 'It is digested rapidly by soil bacteria'], correctIndex: 1, explanation: 'Sporopollenin can withstand high temperatures and strong acids/alkalis, and no enzyme capable of degrading it is currently known.', difficulty: 'medium' },
  { id: 'srfp-29', type: 'mcq', question: 'Due to the highly resistant nature of sporopollenin, pollen grain exine is well preserved as fossils; the study of pollen grains and spores (including their fossil forms) is called:', options: ['Cytology', 'Embryology', 'Palaeobotany', 'Palynology'], correctIndex: 3, explanation: 'Palynology is the branch of study dealing with pollen grains and spores, including their fossilised forms preserved due to sporopollenin\'s resistance.', difficulty: 'medium' },
  { id: 'srfp-30', type: 'mcq', question: 'Sporopollenin exine displays prominent apertures, thin areas where sporopollenin is absent, referred to as:', options: ['Micropyle', 'Chalaza', 'Germ pores', 'Hilum'], correctIndex: 2, explanation: 'The exine has germ pores — regions lacking sporopollenin — through which the pollen tube emerges during germination.', difficulty: 'medium' },
  { id: 'srfp-31', type: 'mcq', question: 'The intine, the inner wall layer of the pollen grain, is a thin and continuous layer made up of:', options: ['Chitin', 'Sporopollenin', 'Cellulose and pectin', 'Lignin and suberin'], correctIndex: 2, explanation: 'Intine is a thin, continuous layer made of cellulose and pectin, unlike the resistant, sporopollenin-based exine.', difficulty: 'medium' },
  { id: 'srfp-32', type: 'mcq', question: 'At the time of shedding, a pollen grain is typically at which cellular stage in most angiosperms?', options: ['A single-celled, unicellular structure', 'A two-celled structure (vegetative cell and generative cell)', 'A four-celled structure', 'A structure with eight free nuclei'], correctIndex: 1, explanation: 'At the time of shedding, a pollen grain is generally two-celled: a bigger vegetative cell and a smaller generative cell.', difficulty: 'medium' },
  { id: 'srfp-33', type: 'mcq', question: 'Of the two cells present in a shed pollen grain, the vegetative cell is characterised by:', options: ['Lacking cytoplasm entirely', 'An irregular nucleus and abundant food reserve', 'A prominent, dense spindle shape and dense cytoplasm only', 'Being smaller than the generative cell'], correctIndex: 1, explanation: 'The vegetative cell is bigger than the generative cell, has abundant food reserve, and possesses an irregularly shaped nucleus.', difficulty: 'medium' },
  { id: 'srfp-34', type: 'mcq', question: 'The generative cell of a pollen grain, in contrast to the vegetative cell, is typically:', options: ['Fused permanently with the vegetative cell nucleus', 'Large, star-shaped, and located at the periphery', 'Absent in most flowering plants', 'Small and spindle-shaped, lying freely in the cytoplasm of the vegetative cell'], correctIndex: 3, explanation: 'The generative cell is small and spindle- or spherical-shaped with dense cytoplasm and a nucleus, floating freely in the cytoplasm of the vegetative cell.', difficulty: 'medium' },
  { id: 'srfp-35', type: 'mcq', question: 'In about 60 per cent of angiosperms, pollen grains are shed at the two-celled stage; in the remaining species, the pollen is shed at the three-celled stage because:', options: ['The vegetative cell divides into two vegetative cells', 'The pollen grain fuses with another pollen grain', 'Meiosis occurs a second time within the pollen grain', 'The generative cell divides mitotically to form two male gametes before shedding'], correctIndex: 3, explanation: 'In about 40% of angiosperms, the generative cell divides mitotically within the pollen grain itself to produce two male gametes before the pollen is shed, resulting in a three-celled pollen grain at shedding.', difficulty: 'hard' },
  { id: 'srfp-36', type: 'assertion-reason', question: 'Assertion (A): Pollen grains of several plant species cause severe allergies and respiratory disorders in some individuals.\nReason (R): Common examples of allergenic plants include Parthenium (carrot grass), whose pollen can lead to chronic respiratory disorders such as asthma and bronchitis.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The example of Parthenium causing chronic respiratory disorders correctly illustrates and explains why pollen allergies are a documented concern.', difficulty: 'medium' },
  { id: 'srfp-37', type: 'mcq', question: 'Pollen grains, being rich in nutrients, are also commercially used as:', options: ['A source of drinking water', 'Only as agricultural fertiliser', 'A raw material for producing antibiotics', 'Health food supplements available in the form of tablets and syrups'], correctIndex: 3, explanation: 'Due to their nutritive value, pollen tablets and syrups are commercially available and are claimed to improve the performance of athletes and race horses.', difficulty: 'medium' },
  { id: 'srfp-38', type: 'mcq', question: 'Pollen grains can be stored for years for use in crop breeding programmes; a common method used for such long-term storage is:', options: ['Storage at room temperature indefinitely without any special treatment', 'Storage in liquid nitrogen at -196°C (pollen cryopreservation)', 'Boiling the pollen at high temperature before storage', 'Storage in strong acid solution'], correctIndex: 1, explanation: 'Pollen grains can be preserved for years in liquid nitrogen (-196°C) and used in crop breeding programmes, similar to a "pollen/germplasm bank".', difficulty: 'medium' },
  { id: 'srfp-39', type: 'assertion-reason', question: 'Assertion (A): The pollen exine has well-defined thin areas called germ pores.\nReason (R): Germ pores are the specific sites where sporopollenin is absent, allowing the pollen tube to emerge easily during germination.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The absence of sporopollenin at germ pores directly explains why the pollen tube emerges specifically from these regions, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'srfp-40', type: 'how-many', question: 'Consider the following statements about the pollen grain:\n1. The pollen grain is the male gametophyte of flowering plants.\n2. Exine is made of sporopollenin, and no enzyme is known to degrade it.\n3. Intine is made of sporopollenin, similar to the exine.\n4. Germ pores are regions of the exine where sporopollenin is absent.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — intine is made of cellulose and pectin, not sporopollenin.', difficulty: 'medium' },
  { id: 'srfp-41', type: 'how-many', question: 'Consider the following statements about the pollen grain at the time of shedding:\n1. About 60% of angiosperm species shed pollen at the two-celled stage.\n2. The vegetative cell is generally smaller than the generative cell.\n3. In roughly 40% of angiosperms, the generative cell divides mitotically before shedding, producing two male gametes.\n4. The generative cell has abundant food reserves and an irregular nucleus.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (the vegetative cell is bigger, not smaller), and statement 4 is wrong (that description fits the vegetative cell, not the generative cell).', difficulty: 'hard' },
  { id: 'srfp-42', type: 'statement', question: 'Statement I: Pollen allergies can be a significant public health concern in certain regions and seasons.\nStatement II: All pollen grains, regardless of species, cause the same intensity of allergic response in every individual.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — allergic response varies with pollen species, individual sensitivity and exposure levels; it is not the same for all pollen and all individuals.', difficulty: 'medium' },

  // ============ PISTIL AND OVULE STRUCTURE ============
  { id: 'srfp-44', type: 'mcq', question: 'The ovary of the pistil encloses one or more:', options: ['Pollen sacs', 'Microsporangia', 'Ovules, attached to the placenta', 'Anthers'], correctIndex: 2, explanation: 'The ovary encloses ovules attached to the placenta; each ovule ultimately develops into a seed after fertilisation.', difficulty: 'easy' },
  { id: 'srfp-45', type: 'mcq', question: 'The stalk by which an ovule is attached to the placenta is called the:', options: ['Funicle', 'Hilum', 'Micropyle', 'Chalaza'], correctIndex: 0, explanation: 'The funicle is the stalk that attaches the ovule to the placenta.', difficulty: 'easy' },
  { id: 'srfp-46', type: 'mcq', question: 'The junction between the funicle and the body of the ovule is called the:', options: ['Hilum', 'Chalaza', 'Nucellus', 'Micropyle'], correctIndex: 0, explanation: 'The hilum is the point of junction between the funicle and the body of the ovule.', difficulty: 'easy' },
  { id: 'srfp-47', type: 'mcq', question: 'The protective envelope(s) that surround the ovule, except at the tip where a small opening remains, are called:', options: ['Nucellus', 'Perianth', 'Testa', 'Integuments'], correctIndex: 3, explanation: 'The ovule usually has one or two protective envelopes called integuments, which encircle the nucellus except for a small opening (micropyle).', difficulty: 'easy' },
  { id: 'srfp-48', type: 'mcq', question: 'The small pore or opening formed by the integuments at the tip of the ovule is called the:', options: ['Chalaza', 'Micropyle', 'Funicle', 'Hilum'], correctIndex: 1, explanation: 'The micropyle is the small opening at the tip of the ovule, formed by the integuments, through which the pollen tube commonly enters.', difficulty: 'easy' },
  { id: 'srfp-49', type: 'mcq', question: 'The basal part of the ovule, situated opposite to the micropyle, where the body of the ovule fuses with the integuments and funicle, is called the:', options: ['Nucellus', 'Chalaza', 'Raphe', 'Hilum'], correctIndex: 1, explanation: 'Chalaza is the basal region of the ovule, opposite the micropylar end, where the integuments fuse with the body of the ovule.', difficulty: 'medium' },
  { id: 'srfp-50', type: 'mcq', question: 'The mass of nutritive tissue that occupies the centre of the ovule, enclosed by the integuments, is called the:', options: ['Endosperm', 'Testa', 'Perisperm', 'Nucellus'], correctIndex: 3, explanation: 'The nucellus is a mass of cells enclosed within the integuments, which contains reserve food materials.', difficulty: 'easy' },
  { id: 'srfp-51', type: 'mcq', question: 'The single, large, functional cell present within the nucellus tissue of the ovule, from which the female gametophyte later develops, is called the:', options: ['Synergid cell', 'Megaspore mother cell (MMC)', 'Antipodal cell', 'Pollen mother cell'], correctIndex: 1, explanation: 'The megaspore mother cell (MMC) is a large cell present in the micropylar region of the nucellus, which undergoes meiosis to form megaspores.', difficulty: 'medium' },
  { id: 'srfp-52', type: 'mcq', question: 'The megaspore mother cell (MMC) of an ovule is a diploid cell containing:', options: ['Two nuclei permanently', 'No cytoplasm at all', 'A permanently vacuolated cytoplasm without a nucleus', 'A dense cytoplasm and a prominent nucleus'], correctIndex: 3, explanation: 'The MMC is a large cell with dense cytoplasm and a prominent nucleus, distinguishing it from other nucellar cells.', difficulty: 'medium' },
  { id: 'srfp-53', type: 'assertion-reason', question: 'Assertion (A): The micropyle plays an important role even after fertilisation.\nReason (R): The micropyle generally serves as the passage through which the pollen tube enters the ovule, and later remains as a small pore in the seed coat facilitating entry of water/oxygen during germination.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The dual role of the micropyle — as an entry point for the pollen tube during fertilisation and later for water/oxygen entry during seed germination — correctly explains its ongoing importance.', difficulty: 'medium' },
  { id: 'srfp-54', type: 'how-many', question: 'Consider the following statements about ovule structure:\n1. The funicle attaches the ovule to the placenta.\n2. The hilum is the junction between the funicle and the ovule body.\n3. The chalaza is located at the same end as the micropyle.\n4. The nucellus contains reserve food material and is enclosed by the integuments.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the chalaza is located at the basal end, opposite to the micropyle.', difficulty: 'medium' },

  // ============ MEGASPOROGENESIS AND TYPES OF OVULES ============
  { id: 'srfp-56', type: 'mcq', question: 'The process by which megaspores are formed from the megaspore mother cell is called:', options: ['Karyogamy', 'Microsporogenesis', 'Megasporogenesis', 'Gametogenesis'], correctIndex: 2, explanation: 'Megasporogenesis is the process of megaspore formation from the megaspore mother cell (MMC) through meiosis.', difficulty: 'easy' },
  { id: 'srfp-57', type: 'mcq', question: 'The megaspore mother cell undergoes meiotic division to produce:', options: ['Four megaspores, arranged as a linear or T-shaped tetrad', 'Two megaspores', 'A single, undivided megaspore only', 'Eight megaspores'], correctIndex: 0, explanation: 'The MMC undergoes meiosis to produce four haploid megaspores, typically arranged in a linear or T-shaped tetrad.', difficulty: 'medium' },
  { id: 'srfp-58', type: 'mcq', question: 'In most flowering plants, out of the four megaspores formed, how many typically remain functional and develop further into the female gametophyte?', options: ['None of the megaspores develop further', 'All four megaspores develop simultaneously', 'Only one megaspore remains functional, while the other three degenerate', 'Exactly two megaspores develop'], correctIndex: 2, explanation: 'In most angiosperms, only one megaspore remains functional while the other three degenerate; this pattern is called monosporic development of the female gametophyte.', difficulty: 'medium' },
  { id: 'srfp-59', type: 'mcq', question: 'The pattern of female gametophyte development in which only one of the four megaspores contributes to the female gametophyte is called:', options: ['Monosporic development', 'Polysporic development', 'Tetrasporic development', 'Bisporic development'], correctIndex: 0, explanation: 'Monosporic development is the most common pattern, in which only one functional megaspore forms the female gametophyte.', difficulty: 'medium' },
  { id: 'srfp-60', type: 'assertion-reason', question: 'Assertion (A): Not all four megaspores produced by meiosis of the MMC contribute to the formation of the female gametophyte in most angiosperms.\nReason (R): In the common monosporic pattern of development, only one of the four megaspores remains functional, while the remaining three degenerate.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The monosporic pattern of female gametophyte development, in which three of the four megaspores degenerate, correctly explains why only one contributes to gametophyte formation.', difficulty: 'medium' },
  { id: 'srfp-61', type: 'how-many', question: 'Consider the following statements about megasporogenesis:\n1. The MMC is diploid and undergoes meiosis to form megaspores.\n2. Four megaspores are typically produced from one MMC.\n3. In most angiosperms, all four megaspores are equally functional and develop into embryo sacs.\n4. Monosporic development is the most common pattern of female gametophyte formation.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — in most angiosperms, only one megaspore remains functional (monosporic development), not all four.', difficulty: 'medium' },
  { id: 'srfp-62', type: 'mcq', question: 'An ovule in which the micropyle, chalaza and funicle all lie in one straight vertical line, with the body of the ovule remaining straight, is called:', options: ['Circinotropous', 'Orthotropous (atropous)', 'Campylotropous', 'Anatropous'], correctIndex: 1, explanation: 'An orthotropous (atropous) ovule is straight, with the micropyle, chalaza and funicle lying in a straight line.', difficulty: 'hard' },
  { id: 'srfp-63', type: 'mcq', question: 'The most common type of ovule in flowering plants, in which the body of the ovule bends around so that the micropyle comes to lie close to the funicle, is called:', options: ['Campylotropous', 'Orthotropous', 'Amphitropous', 'Anatropous'], correctIndex: 3, explanation: 'The anatropous ovule, in which the ovule body is inverted (bent 180°) so that the micropyle lies close to the funicle, is the most common ovule type in angiosperms.', difficulty: 'hard' },

  // ============ FEMALE GAMETOPHYTE (EMBRYO SAC) DEVELOPMENT ============
  { id: 'srfp-64', type: 'mcq', question: 'The functional megaspore develops into the female gametophyte, more commonly known as the:', options: ['Pollen grain', 'Zygote', 'Endosperm', 'Embryo sac'], correctIndex: 3, explanation: 'The functional megaspore undergoes successive divisions to form the female gametophyte, commonly called the embryo sac.', difficulty: 'easy' },
  { id: 'srfp-65', type: 'mcq', question: 'The nucleus of the functional megaspore divides mitotically to first form a stage in embryo sac development known as the:', options: ['8-nucleate embryo sac', '1-nucleate embryo sac (no division)', '4-nucleate embryo sac', '2-nucleate embryo sac'], correctIndex: 3, explanation: 'The functional megaspore nucleus divides mitotically to form two nuclei, which move to opposite poles, forming the 2-nucleate embryo sac stage.', difficulty: 'medium' },
  { id: 'srfp-66', type: 'mcq', question: 'Following two more sequential mitotic divisions from the 2-nucleate stage, the embryo sac reaches which stage before cell wall formation begins?', options: ['4-nucleate stage', '8-nucleate stage', '3-nucleate stage', '16-nucleate stage'], correctIndex: 1, explanation: 'From the 2-nucleate stage, two more mitotic divisions result in the formation of a typical 8-nucleate embryo sac, after which cellularisation occurs.', difficulty: 'medium' },
  { id: 'srfp-67', type: 'mcq', question: 'Despite having 8 nuclei, a mature typical embryo sac is described as 7-celled because:', options: ['One nucleus degenerates before cellularisation', 'All 8 nuclei fuse into a single nucleus', 'Only 6 nuclei survive to maturity', 'The two polar nuclei remain uncellularised together within a large central cell'], correctIndex: 3, explanation: 'Cellularisation occurs around 6 of the 8 nuclei, while the remaining two polar nuclei stay together, uncellularised, in a large central cell — resulting in a 7-celled, 8-nucleate embryo sac.', difficulty: 'hard' },
  { id: 'srfp-68', type: 'mcq', question: 'The group of three cells present at the micropylar end of a mature embryo sac, consisting of one egg cell and two synergids, is collectively called the:', options: ['Antipodal complex', 'Egg apparatus', 'Polar nuclei group', 'Chalazal complex'], correctIndex: 1, explanation: 'The egg apparatus, located at the micropylar end of the embryo sac, consists of one egg cell and two synergids.', difficulty: 'medium' },
  { id: 'srfp-69', type: 'mcq', question: 'The cells flanking the egg cell in the egg apparatus, which help guide the pollen tube into the embryo sac, are called:', options: ['Nucellar cells', 'Polar nuclei', 'Synergids', 'Antipodals'], correctIndex: 2, explanation: 'The two synergid cells flank the egg cell in the egg apparatus and play a role in guiding the pollen tube into the embryo sac.', difficulty: 'medium' },
  { id: 'srfp-70', type: 'mcq', question: 'The synergid cells possess special cellular thickenings at their micropylar tip, collectively called the:', options: ['Chalazal plug', 'Filiform apparatus', 'Perisperm', 'Aleurone layer'], correctIndex: 1, explanation: 'Synergid cells have special thickenings at their micropylar tip, known as the filiform apparatus, which help guide the entering pollen tube.', difficulty: 'medium' },
  { id: 'srfp-71', type: 'mcq', question: 'The three cells present at the chalazal end of the mature embryo sac are collectively known as the:', options: ['Synergid group', 'Antipodal cells', 'Central cell complex', 'Egg apparatus'], correctIndex: 1, explanation: 'The antipodal cells, three in number, are located at the chalazal end of the mature embryo sac.', difficulty: 'medium' },
  { id: 'srfp-72', type: 'mcq', question: 'The large central cell of the mature embryo sac contains two nuclei, called polar nuclei, that are:', options: ['Not surrounded by any cell wall and lie free within the central cell', 'Individually surrounded by their own cell wall', 'Fused before pollination in all angiosperms', 'Located at the micropylar end along with the egg apparatus'], correctIndex: 0, explanation: 'The two polar nuclei remain free, without a cell wall around them, situated in the large central cell of the mature embryo sac.', difficulty: 'medium' },
  { id: 'srfp-73', type: 'mcq', question: 'The typical mature angiosperm female gametophyte (embryo sac) can be summarised as being:', options: ['7-nucleate and 7-celled', '8-nucleate and 8-celled', '6-nucleate and 6-celled', '8-nucleate and 7-celled'], correctIndex: 3, explanation: 'A typical mature embryo sac is 8-nucleate but 7-celled, since the two polar nuclei share a single large central cell without individual cell walls.', difficulty: 'medium' },
  { id: 'srfp-74', type: 'assertion-reason', question: 'Assertion (A): The polar nuclei of the embryo sac usually fuse with each other before fertilisation, forming a secondary nucleus, in many species.\nReason (R): The union of the two polar nuclei prepares the central cell for triple fusion with a male gamete, ultimately giving rise to the triploid primary endosperm nucleus.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The eventual role of the polar nuclei (or their fusion product) in triple fusion, leading to endosperm formation, correctly explains their behaviour as described in the assertion.', difficulty: 'hard' },
  { id: 'srfp-75', type: 'assertion-reason', question: 'Assertion (A): The filiform apparatus of the synergid cell is functionally significant during fertilisation.\nReason (R): The filiform apparatus helps guide the pollen tube as it grows towards and enters the synergid cell of the embryo sac.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The guiding role of the filiform apparatus in pollen tube entry directly explains its functional significance, correctly matching the assertion.', difficulty: 'medium' },
  { id: 'srfp-76', type: 'how-many', question: 'Consider the following statements about embryo sac development:\n1. The functional megaspore divides mitotically to reach an 8-nucleate stage before cellularisation.\n2. A typical mature embryo sac is 7-celled despite having 8 nuclei.\n3. Antipodal cells are located at the micropylar end of the embryo sac.\n4. The egg apparatus consists of one egg cell and two synergids.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — antipodal cells are located at the chalazal end, not the micropylar end.', difficulty: 'medium' },
  { id: 'srfp-77', type: 'how-many', question: 'Consider the following statements about the egg apparatus:\n1. It is located at the chalazal end of the embryo sac.\n2. It consists of two synergids and one egg cell.\n3. Synergids possess a filiform apparatus at their micropylar tip.\n4. The egg cell is the female gamete that fuses with a male gamete during syngamy.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 2, 3 and 4 are correct. Statement 1 is wrong — the egg apparatus is located at the micropylar end, not the chalazal end.', difficulty: 'medium' },
  { id: 'srfp-79', type: 'statement', question: 'Statement I: In a typical angiosperm, the female gametophyte develops from a single functional megaspore through free nuclear divisions followed by cellularisation.\nStatement II: All angiosperm species follow exactly the same pattern of embryo sac development, with no variation whatsoever.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I correctly describes the typical (monosporic) pattern. Statement II is incorrect — variations exist among species (e.g., bisporic, tetrasporic development in some plants).', difficulty: 'medium' },

  // ============ POLLINATION: TYPES ============
  { id: 'srfp-80', type: 'mcq', question: 'The transfer of pollen grains from the anther to the stigma of a flower is called:', options: ['Gametogenesis', 'Fertilisation', 'Germination', 'Pollination'], correctIndex: 3, explanation: 'Pollination is the process by which pollen grains are transferred from the anther to the stigma of a flower.', difficulty: 'easy' },
  { id: 'srfp-81', type: 'mcq', question: 'The transfer of pollen grains from the anther to the stigma of the same flower is called:', options: ['Xenogamy', 'Autogamy', 'Chasmogamy', 'Geitonogamy'], correctIndex: 1, explanation: 'Autogamy refers to self-pollination, where pollen is transferred from the anther to the stigma of the same flower.', difficulty: 'easy' },
  { id: 'srfp-82', type: 'mcq', question: 'For autogamy to occur, which two conditions are generally necessary?', options: ['Presence of a pollinating agent and cross-compatibility', 'Presence of two different plants of the same species', 'Synchrony in pollen release and stigma receptivity, with anthers and stigma positioned close to each other', 'Presence of only wind as pollinating agent'], correctIndex: 2, explanation: 'Autogamy requires synchrony between pollen release and stigma receptivity, and the anther and stigma need to lie close together within the same flower.', difficulty: 'medium' },
  { id: 'srfp-83', type: 'mcq', question: 'Flowers that never open at all, ensuring autogamy, are described as:', options: ['Chasmogamous', 'Zygomorphic', 'Epigynous', 'Cleistogamous'], correctIndex: 3, explanation: 'Cleistogamous flowers never open, and since the anthers and stigma lie close together, they inherently favour autogamy, as in Viola, Oxalis and Commelina.', difficulty: 'medium' },
  { id: 'srfp-84', type: 'mcq', question: 'Which of the following genera are commonly cited examples of plants that produce cleistogamous flowers?', options: ['Viola, Oxalis and Commelina', 'Mango and Citrus', 'Vallisneria, Hydrilla and Zostera', 'Yucca and Ficus'], correctIndex: 0, explanation: 'Viola, Oxalis and Commelina are common examples of plants that produce cleistogamous flowers, ensuring autogamy.', difficulty: 'medium' },
  { id: 'srfp-85', type: 'mcq', question: 'The transfer of pollen grains from the anther of one flower to the stigma of a different flower borne on the same plant is called:', options: ['Autogamy', 'Cleistogamy', 'Geitonogamy', 'Xenogamy'], correctIndex: 2, explanation: 'Geitonogamy involves pollen transfer between different flowers on the same plant; it requires a pollinating agent but is genetically similar to autogamy since the pollen source is the same plant.', difficulty: 'medium' },
  { id: 'srfp-86', type: 'mcq', question: 'The transfer of pollen grains from the anther of a flower on one plant to the stigma of a flower on a genetically different plant of the same species is called:', options: ['Cleistogamy', 'Xenogamy', 'Geitonogamy', 'Autogamy'], correctIndex: 1, explanation: 'Xenogamy involves the transfer of pollen between two genetically different plants of the same species, bringing genetically different pollen to the stigma.', difficulty: 'easy' },
  { id: 'srfp-87', type: 'assertion-reason', question: 'Assertion (A): Geitonogamy is genetically similar to autogamy though it requires a pollinating agent.\nReason (R): In geitonogamy, though pollen is physically transferred to a different flower, both the flowers involved belong to the same plant, so the genetic outcome resembles self-pollination.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since both flowers in geitonogamy share the same genetic makeup (same plant), the process is genetically equivalent to self-pollination, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'srfp-88', type: 'assertion-reason', question: 'Assertion (A): Xenogamy is the only type of pollination that brings genetically different pollen grains to the stigma.\nReason (R): Xenogamy involves pollen transfer between flowers of two different, genetically distinct plants of the same species, unlike autogamy and geitonogamy which involve the same plant.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since xenogamy alone involves two genetically distinct plants, it uniquely introduces genetically different pollen to the stigma, correctly matching the assertion and reason.', difficulty: 'medium' },
  { id: 'srfp-89', type: 'how-many', question: 'Consider the following statements about pollination types:\n1. Autogamy refers to pollen transfer within the same flower.\n2. Geitonogamy involves pollen transfer between two genetically different plants.\n3. Cleistogamous flowers never open and inherently ensure autogamy.\n4. Xenogamy introduces genetically different pollen to the stigma.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — geitonogamy involves flowers on the same plant, not two different plants.', difficulty: 'medium' },
  { id: 'srfp-90', type: 'statement', question: 'Statement I: Geitonogamy requires a pollinating agent, just like xenogamy.\nStatement II: Geitonogamy results in genetic outcomes identical to xenogamy, since pollen is physically transferred between two different flowers.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — despite physical transfer between two flowers, geitonogamy is genetically equivalent to autogamy (same plant), not to xenogamy (different plants).', difficulty: 'medium' },

  // ============ POLLINATION: AGENTS ============
  { id: 'srfp-92', type: 'mcq', question: 'Pollination carried out with the help of abiotic agents such as wind and water is called, respectively:', options: ['Entomophily and ornithophily', 'Zoophily and chiropterophily', 'Anemophily and hydrophily', 'Malacophily and anemophily'], correctIndex: 2, explanation: 'Wind pollination is called anemophily, and water pollination is called hydrophily; both are examples of abiotic pollination.', difficulty: 'easy' },
  { id: 'srfp-93', type: 'mcq', question: 'Pollination carried out with the help of biotic agents, such as insects, birds and bats, is broadly termed:', options: ['Autogamy', 'Anemophily', 'Hydrophily', 'Zoophily'], correctIndex: 3, explanation: 'Zoophily refers to biotic pollination carried out with the help of animals, which may be insects, birds, bats or other animals.', difficulty: 'easy' },
  { id: 'srfp-94', type: 'mcq', question: 'Flowers pollinated by wind typically show which of the following adaptations?', options: ['Flowers with heavy, large pollen grains', 'Brightly coloured, large, strongly scented flowers with sticky pollen', 'Flowers that produce no pollen at all', 'Small, dull-coloured flowers, well-exposed stamens, light and non-sticky pollen grains, and a large feathery stigma'], correctIndex: 3, explanation: 'Wind-pollinated (anemophilous) flowers are typically small, dull-coloured, produce a large amount of light, non-sticky pollen, have well-exposed stamens, and often have a large, often feathery stigma to trap airborne pollen.', difficulty: 'medium' },
  { id: 'srfp-95', type: 'mcq', question: 'Grasses, being wind-pollinated, are known to produce which of the following in relation to pollen?', options: ['A very small number of pollen grains per flower', 'An enormous number of pollen grains per flower, compensating for pollen loss during wind transport', 'Only sterile pollen grains', 'No pollen grains at all'], correctIndex: 1, explanation: 'Wind-pollinated flowers such as grasses produce enormous numbers of pollen grains to increase the chance of successful pollination, since much of the pollen is lost during wind dispersal.', difficulty: 'medium' },
  { id: 'srfp-96', type: 'mcq', question: 'Water pollination (hydrophily) is a relatively uncommon phenomenon, occurring in only about how many genera of flowering plants, mostly monocots?', options: ['About 300 genera', 'About 30 genera', 'About 3000 genera', 'About 30,000 genera'], correctIndex: 1, explanation: 'Water pollination occurs in only about 30 genera, mostly monocots, showing that hydrophily is relatively rare among angiosperms.', difficulty: 'medium' },
  { id: 'srfp-97', type: 'mcq', question: 'In many hydrophilous (water-pollinated) plants, pollen grains are often protected from wetting by a covering of:', options: ['Wax', 'Cellulose', 'Chitin', 'Mucilage'], correctIndex: 3, explanation: 'In several water-pollinated species, pollen grains are protected from getting wet by a covering of mucilage.', difficulty: 'medium' },
  { id: 'srfp-98', type: 'mcq', question: 'In marine sea grasses such as Zostera, water pollination is aided by pollen grains that are:', options: ['Extremely heavy and immediately sink to the ocean floor', 'Spherical and coated with a sticky substance for insect attachment', 'Absent, as fertilisation occurs vegetatively', 'Long and ribbon-like, facilitating easy contact with the stigma'], correctIndex: 3, explanation: 'In Zostera, a marine angiosperm, pollen grains are long and ribbon-like, an adaptation that facilitates water pollination by increasing the chance of contact with the elongated stigma.', difficulty: 'hard' },
  { id: 'srfp-99', type: 'mcq', question: 'In the freshwater plant Vallisneria, the female flowers reach the water surface by means of:', options: ['Floating leaves', 'Long, coiled stalks', 'Sticky adhesive threads', 'Air-filled bracts'], correctIndex: 1, explanation: 'Vallisneria has female flowers that reach the surface of water with the help of long stalks, where they receive pollen released by male flowers on the water surface.', difficulty: 'hard' },
  { id: 'srfp-100', type: 'mcq', question: 'Entomophilous (insect-pollinated) flowers commonly show which of the following adaptations?', options: ['Extremely small size and lack of stamens', 'Bright colour, fragrance, nectar, and sticky pollen grains adapted to attach to the insect body', 'Absence of nectar and no scent whatsoever', 'Dull colour, no fragrance, and light non-sticky pollen'], correctIndex: 1, explanation: 'Insect-pollinated flowers are generally colourful, fragrant, produce nectar, and have relatively larger, sticky pollen grains that adhere to the insect body.', difficulty: 'medium' },
  { id: 'srfp-101', type: 'mcq', question: 'Ornithophilous (bird-pollinated) flowers, such as those pollinated by sunbirds and hummingbirds, are typically:', options: ['Pollinated only at night', 'Devoid of nectar entirely', 'Small, dull-coloured, and always strongly scented', 'Large, brightly coloured, generally odourless, and produce nectar'], correctIndex: 3, explanation: 'Bird-pollinated flowers are typically large, colourful and usually odourless (since birds do not rely much on smell), and they produce nectar to attract birds.', difficulty: 'medium' },
  { id: 'srfp-102', type: 'mcq', question: 'Bat-pollinated flowers, adapted for chiropterophily, are typically:', options: ['Adapted exclusively for water dispersal', 'Entirely scentless and closed permanently', 'Large, dull-coloured, and open during the night with a strong odour', 'Small, brightly coloured, and open only during the day'], correctIndex: 2, explanation: 'Flowers pollinated by bats (chiropterophily) are usually large, dull-coloured, open at night and have a strong odour to attract nocturnal bats.', difficulty: 'medium' },
  { id: 'srfp-103', type: 'assertion-reason', question: 'Assertion (A): Wind-pollinated flowers generally produce a very large number of pollen grains.\nReason (R): Wind is a relatively inefficient and non-directional pollinating agent, so most pollen grains fail to reach the stigma, necessitating large-scale pollen production to ensure successful pollination.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The inefficiency of wind as a pollinating agent, causing most pollen to be lost, correctly explains why wind-pollinated flowers must produce large amounts of pollen.', difficulty: 'medium' },
  { id: 'srfp-104', type: 'assertion-reason', question: 'Assertion (A): Bird-pollinated flowers are usually odourless.\nReason (R): Birds generally have a poor sense of smell, so flowers pollinated by them rely mainly on bright visual cues (colour) rather than fragrance to attract pollinators.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since birds have a poor sense of smell, relying instead on vision, this correctly explains why bird-pollinated flowers do not depend on fragrance.', difficulty: 'medium' },
  { id: 'srfp-105', type: 'how-many', question: 'Consider the following statements about pollination agents:\n1. Anemophily refers to wind pollination.\n2. Hydrophily is a very common mode of pollination found in most angiosperm species.\n3. Entomophilous flowers are typically colourful and fragrant.\n4. Chiropterophily refers to pollination by bats.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — hydrophily is relatively rare, occurring in only about 30 genera, mostly monocots.', difficulty: 'medium' },
  { id: 'srfp-106', type: 'how-many', question: 'Consider the following statements about wind-pollinated (anemophilous) flowers:\n1. They generally have well-exposed stamens for easy pollen dispersal.\n2. Their pollen grains are light and non-sticky.\n3. Their stigma is often large and feathery to trap air-borne pollen.\n4. They typically produce very little pollen since wind carries pollen efficiently.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — anemophilous flowers actually produce enormous amounts of pollen to compensate for the inefficiency of wind pollination.', difficulty: 'medium' },
  { id: 'srfp-107', type: 'how-many', question: 'Consider the following plants:\n1. Vallisneria\n2. Zostera\n3. Hydrilla\n4. Mango\n5. Sunflower\nHow many of the above are commonly cited examples of water-pollinated (hydrophilous) plants?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Vallisneria, Zostera and Hydrilla are examples of hydrophilous plants. Mango and sunflower are pollinated by insects, not water.', difficulty: 'medium' },
  { id: 'srfp-108', type: 'statement', question: 'Statement I: Zoophily, or animal pollination, includes pollination by insects, birds, bats, and even some other animals.\nStatement II: Entomophily is generally considered the most common form of biotic pollination among flowering plants.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly reflect the diversity of zoophily and the prominence of insects (entomophily) as the most common biotic pollinators.', difficulty: 'medium' },

  // ============ OUTBREEDING DEVICES ============
  { id: 'srfp-110', type: 'mcq', question: 'Mechanisms present in many flowering plants that prevent self-pollination and promote cross-pollination are collectively known as:', options: ['Inbreeding devices', 'Outbreeding devices', 'Vegetative propagation devices', 'Apomictic devices'], correctIndex: 1, explanation: 'Outbreeding devices are mechanisms evolved by flowering plants to discourage self-pollination and favour cross-pollination (xenogamy).', difficulty: 'easy' },
  { id: 'srfp-111', type: 'mcq', question: 'One outbreeding device involves the flower being unisexual, so that only either male or female reproductive parts are present; this condition is called:', options: ['Dicliny (unisexuality)', 'Self-incompatibility', 'Herkogamy', 'Dichogamy'], correctIndex: 0, explanation: 'Dicliny refers to the condition of unisexual flowers, either monoecious (male and female flowers on the same plant) or dioecious (on different plants), which prevents autogamy.', difficulty: 'medium' },
  { id: 'srfp-112', type: 'mcq', question: 'An outbreeding device in which the anther and stigma of a bisexual flower mature at different times, thus preventing autogamy, is called:', options: ['Dicliny', 'Dichogamy', 'Chasmogamy', 'Herkogamy'], correctIndex: 1, explanation: 'Dichogamy involves maturation of the anther and stigma at different times in the same flower, preventing self-pollination even in bisexual flowers.', difficulty: 'medium' },
  { id: 'srfp-113', type: 'mcq', question: 'When the anther of a bisexual flower matures earlier than the stigma, this specific type of dichogamy is called:', options: ['Protogyny', 'Cleistogamy', 'Herkogamy', 'Protandry'], correctIndex: 3, explanation: 'Protandry is the condition where the anther matures before the stigma in a bisexual flower.', difficulty: 'medium' },
  { id: 'srfp-114', type: 'mcq', question: 'When the stigma of a bisexual flower matures earlier than the anther, this specific type of dichogamy is called:', options: ['Cleistogamy', 'Protogyny', 'Protandry', 'Dicliny'], correctIndex: 1, explanation: 'Protogyny is the condition where the stigma becomes receptive before the anthers mature/dehisce in a bisexual flower.', difficulty: 'medium' },
  { id: 'srfp-115', type: 'mcq', question: 'An outbreeding device in which the anther and stigma of a bisexual flower are positioned at different locations, so that pollen cannot easily fall onto the stigma of the same flower, is called:', options: ['Herkogamy', 'Dicliny', 'Dichogamy', 'Self-incompatibility'], correctIndex: 0, explanation: 'Herkogamy involves a physical hindrance to self-pollination, arising from the different positioning of the anthers and stigma within the same flower.', difficulty: 'medium' },
  { id: 'srfp-116', type: 'mcq', question: 'The genetic mechanism that prevents self-pollen (from the same flower or another flower of the same plant) from developing into a functional pollen tube or germinating, thereby ensuring xenogamy, is called:', options: ['Herkogamy', 'Dichogamy', 'Autogamy', 'Self-incompatibility'], correctIndex: 3, explanation: 'Self-incompatibility is a genetic mechanism that inhibits self-pollen germination or pollen tube growth in the pistil, preventing self-fertilisation.', difficulty: 'medium' },
  { id: 'srfp-117', type: 'assertion-reason', question: 'Assertion (A): Bisexual flowers do not always guarantee self-pollination.\nReason (R): Several outbreeding devices, including dichogamy, herkogamy and self-incompatibility, can operate within a bisexual flower to prevent or reduce self-pollination, favouring cross-pollination instead.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The presence of multiple outbreeding devices operating within bisexual flowers correctly explains why such flowers do not automatically guarantee self-pollination.', difficulty: 'medium' },
  { id: 'srfp-118', type: 'assertion-reason', question: 'Assertion (A): Self-incompatibility is considered a more reliable barrier to self-pollination than mere physical separation (herkogamy) of anthers and stigma.\nReason (R): Self-incompatibility acts at the genetic/physiological level, inhibiting pollen germination or pollen tube growth even if self-pollen does manage to land on the stigma.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since self-incompatibility functions even after self-pollen reaches the stigma, it provides a more fail-safe mechanism than physical separation alone, correctly explaining the assertion.', difficulty: 'hard' },
  { id: 'srfp-119', type: 'how-many', question: 'Consider the following statements about outbreeding devices:\n1. Dicliny refers to the unisexual condition of flowers.\n2. Protandry means the stigma matures before the anther.\n3. Herkogamy involves physical separation of the anther and stigma within a flower.\n4. Self-incompatibility is a genetic mechanism that prevents self-pollen from fertilising the same flower.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — protandry means the anther matures before the stigma, which is the opposite of protogyny.', difficulty: 'medium' },
  { id: 'srfp-120', type: 'how-many', question: 'Consider the following outbreeding devices:\n1. Dichogamy\n2. Herkogamy\n3. Self-incompatibility\n4. Dicliny\n5. Cleistogamy\nHow many of the above are mechanisms that primarily promote cross-pollination rather than self-pollination?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'Dichogamy, herkogamy, self-incompatibility and dicliny all promote cross-pollination. Cleistogamy, by contrast, ensures self-pollination since the flower never opens.', difficulty: 'medium' },
  { id: 'srfp-121', type: 'statement', question: 'Statement I: Protandry and protogyny are both forms of dichogamy that prevent self-pollination within the same flower.\nStatement II: In protandry, the stigma of the flower matures earlier than the anthers.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — in protandry, the anthers mature earlier than the stigma; the reverse describes protogyny.', difficulty: 'medium' },

  // ============ POLLEN-PISTIL INTERACTION ============
  { id: 'srfp-123', type: 'mcq', question: 'The events starting with the deposition of pollen grains on the stigma, up to the entry of pollen tubes into the ovule, are collectively studied under:', options: ['Embryogenesis', 'Apomixis', 'Fertilisation', 'Pollen-pistil interaction'], correctIndex: 3, explanation: 'Pollen-pistil interaction refers to the series of events from pollen deposition on the stigma to the entry of pollen tubes into the ovule.', difficulty: 'easy' },
  { id: 'srfp-124', type: 'mcq', question: 'The pistil has the ability to recognise pollen, whether they belong to the same species (compatible) or different species (incompatible), through:', options: ['Physical size differences alone', 'Colour recognition of pollen', 'Random selection with no recognition mechanism', 'A continuous dialogue involving chemical (protein-protein) interactions between pollen and pistil'], correctIndex: 3, explanation: 'The pistil recognises pollen through a continuous dialogue between the pollen grain and pistil, mediated by protein-protein interactions.', difficulty: 'medium' },
  { id: 'srfp-125', type: 'mcq', question: 'If the pollen grains landing on the stigma are found to be compatible, the pistil generally:', options: ['Encourages pollen germination and pollen tube growth for fertilisation', 'Rejects the pollen through incompatibility responses', 'Destroys the stigma immediately', 'Has no effect on the pollen at all'], correctIndex: 0, explanation: 'When pollen is compatible, the pistil promotes post-pollination events, leading to germination of the pollen grain and eventual fertilisation.', difficulty: 'easy' },
  { id: 'srfp-126', type: 'mcq', question: 'Most commonly, the pollen tube enters the ovule through the micropyle; this common route of entry is termed:', options: ['Zoogamy', 'Mesogamy', 'Chalazogamy', 'Porogamy'], correctIndex: 3, explanation: 'Porogamy is the most common mode of entry, in which the pollen tube enters the ovule through the micropyle.', difficulty: 'medium' },
  { id: 'srfp-127', type: 'mcq', question: 'In some plants, such as Casuarina, the pollen tube enters the ovule through the chalazal end instead of the micropyle; this mode of entry is called:', options: ['Cleistogamy', 'Porogamy', 'Chalazogamy', 'Mesogamy'], correctIndex: 2, explanation: 'Chalazogamy refers to the entry of the pollen tube into the ovule via the chalaza, as seen in Casuarina.', difficulty: 'hard' },
  { id: 'srfp-128', type: 'mcq', question: 'When the pollen tube enters the ovule through the integuments rather than the micropyle or chalaza, the mode of entry is called:', options: ['Porogamy', 'Mesogamy', 'Chalazogamy', 'Apomixis'], correctIndex: 1, explanation: 'Mesogamy refers to entry of the pollen tube through the integuments of the ovule.', difficulty: 'hard' },
  { id: 'srfp-129', type: 'mcq', question: 'After entering the ovule, the pollen tube typically enters the embryo sac by penetrating one of the:', options: ['Antipodal cells', 'Synergids', 'Polar nuclei', 'The egg cell directly'], correctIndex: 1, explanation: 'The pollen tube usually enters the embryo sac through one of the two synergid cells, aided by the filiform apparatus.', difficulty: 'medium' },
  { id: 'srfp-130', type: 'mcq', question: 'On entering a synergid, the pollen tube releases its two male gametes into the:', options: ['Cytoplasm of the synergid', 'Chalaza', 'Nucellus tissue', 'Antipodal cells'], correctIndex: 0, explanation: 'The pollen tube releases the two male gametes into the cytoplasm of the synergid it has entered, from where they move towards the egg cell and central cell.', difficulty: 'medium' },
  { id: 'srfp-131', type: 'assertion-reason', question: 'Assertion (A): Not every pollen grain landing on the stigma is able to achieve fertilisation.\nReason (R): Pollen-pistil interaction involves recognition mechanisms that reject incompatible pollen, either through non-germination on the stigma or inhibition of pollen tube growth within the style.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The rejection of incompatible pollen through recognition mechanisms correctly explains why not all landed pollen achieve fertilisation.', difficulty: 'medium' },
  { id: 'srfp-132', type: 'how-many', question: 'Consider the following statements about pollen-pistil interaction:\n1. Porogamy is the most common mode of pollen tube entry into the ovule.\n2. Chalazogamy refers to pollen tube entry through the micropyle.\n3. The pollen tube most commonly enters the embryo sac via a synergid.\n4. The pistil can distinguish compatible from incompatible pollen through chemical interactions.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — chalazogamy refers to entry through the chalaza, not the micropyle (that is porogamy).', difficulty: 'medium' },
  { id: 'srfp-133', type: 'statement', question: 'Statement I: Once a pollen grain lands on a compatible stigma, it always germinates immediately and grows a pollen tube without any further physiological interaction.\nStatement II: Pollen-pistil interaction is a continuous biochemical dialogue that regulates pollen germination and pollen tube growth.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is an oversimplification and incorrect — the process involves ongoing biochemical regulation, not an automatic, interaction-free event. Statement II is correct.', difficulty: 'medium' },

  // ============ DOUBLE FERTILISATION ============
  { id: 'srfp-134', type: 'mcq', question: 'The fusion of one male gamete with the egg cell, forming the diploid zygote, is called:', options: ['Karyogamy of polar nuclei', 'Triple fusion', 'Apomixis', 'Syngamy'], correctIndex: 3, explanation: 'Syngamy is the fusion of the male gamete with the egg cell, resulting in the formation of a diploid zygote.', difficulty: 'easy' },
  { id: 'srfp-135', type: 'mcq', question: 'The fusion of the second male gamete with the two polar nuclei (or the secondary nucleus) of the central cell is called:', options: ['Cytokinesis', 'Mesogamy', 'Triple fusion', 'Syngamy'], correctIndex: 2, explanation: 'Triple fusion is the fusion of the second male gamete with the two polar nuclei (or the diploid secondary nucleus formed by their fusion), resulting in a triploid primary endosperm nucleus.', difficulty: 'medium' },
  { id: 'srfp-136', type: 'mcq', question: 'Since two distinct fusion events (syngamy and triple fusion) occur within the embryo sac following pollen tube entry, the overall phenomenon is termed:', options: ['Apomixis', 'Parthenocarpy', 'Double fertilisation', 'Vegetative propagation'], correctIndex: 2, explanation: 'The occurrence of two fusion events — syngamy and triple fusion — is together known as double fertilisation, a unique phenomenon in flowering plants.', difficulty: 'easy' },
  { id: 'srfp-137', type: 'mcq', question: 'The scientist credited with discovering the phenomenon of double fertilisation in flowering plants was:', options: ['Gregor Mendel', 'Nawaschin', 'Charles Darwin', 'Robert Hooke'], correctIndex: 1, explanation: 'Double fertilisation was discovered by Nawaschin in 1898.', difficulty: 'medium' },
  { id: 'srfp-138', type: 'mcq', question: 'As a direct outcome of triple fusion, the central cell (after fusion with the second male gamete) becomes the:', options: ['Embryo proper', 'Primary endosperm cell (PEC)', 'Suspensor', 'Zygote'], correctIndex: 1, explanation: 'After triple fusion, the central cell becomes the primary endosperm cell (PEC), and its nucleus is called the primary endosperm nucleus (PEN).', difficulty: 'medium' },
  { id: 'srfp-139', type: 'mcq', question: 'The primary endosperm nucleus (PEN), formed as a result of triple fusion, is:', options: ['Haploid', 'Tetraploid', 'Triploid', 'Diploid'], correctIndex: 2, explanation: 'The PEN is triploid, since it results from the fusion of one haploid male gamete with two haploid polar nuclei (1n + 1n + 1n = 3n).', difficulty: 'medium' },
  { id: 'srfp-140', type: 'mcq', question: 'Double fertilisation is considered a unique feature because it occurs:', options: ['Only during vegetative propagation', 'Only in gymnosperms, never in angiosperms', 'In flowering plants only, and involves two distinct fusion events within the embryo sac', 'In all plant groups, including algae, bryophytes and pteridophytes equally'], correctIndex: 2, explanation: 'Double fertilisation is a unique and defining feature of flowering plants (angiosperms), involving two simultaneous fusion events.', difficulty: 'medium' },
  { id: 'srfp-141', type: 'assertion-reason', question: 'Assertion (A): The primary endosperm nucleus is triploid, whereas the zygote formed by syngamy is diploid.\nReason (R): Syngamy involves the fusion of one male gamete (n) with the egg cell (n), while triple fusion involves the fusion of one male gamete (n) with two polar nuclei (n + n).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The distinct participants and ploidy levels involved in syngamy versus triple fusion correctly explain why the zygote is diploid while the PEN is triploid.', difficulty: 'medium' },
  { id: 'srfp-142', type: 'assertion-reason', question: 'Assertion (A): Double fertilisation ensures that nutritive tissue (endosperm) develops alongside the embryo in the same seed.\nReason (R): Triple fusion, which occurs simultaneously with syngamy, gives rise to the primary endosperm nucleus, which then develops into the endosperm that nourishes the developing embryo.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The simultaneous development of the endosperm through triple fusion correctly explains its coordinated appearance alongside the embryo in the same seed.', difficulty: 'medium' },
  { id: 'srfp-143', type: 'how-many', question: 'Consider the following statements about double fertilisation:\n1. Syngamy results in the formation of a diploid zygote.\n2. Triple fusion involves fusion of a male gamete with the two polar nuclei.\n3. The primary endosperm nucleus formed after triple fusion is diploid.\n4. Double fertilisation was first described by Nawaschin.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the primary endosperm nucleus is triploid, not diploid.', difficulty: 'medium' },
  { id: 'srfp-144', type: 'how-many', question: 'Consider the following statements about the outcomes of double fertilisation:\n1. The zygote eventually develops into the embryo.\n2. The primary endosperm cell eventually develops into the endosperm.\n3. Both fusion events (syngamy and triple fusion) occur in different, unrelated embryo sacs.\n4. Double fertilisation is a phenomenon unique to gymnosperms.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is wrong (both fusions occur in the same embryo sac), and statement 4 is wrong (double fertilisation is unique to angiosperms, not gymnosperms).', difficulty: 'medium' },
  { id: 'srfp-145', type: 'statement', question: 'Statement I: Syngamy and triple fusion are two separate fusion events that both occur within the same embryo sac after pollen tube entry.\nStatement II: The term "double fertilisation" refers to the fact that fertilisation occurs twice, once in each of two separate flowers.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — double fertilisation refers to two fusion events within a single embryo sac, not fertilisation occurring in two separate flowers.', difficulty: 'medium' },

  // ============ ENDOSPERM DEVELOPMENT ============
  { id: 'srfp-146', type: 'mcq', question: 'The primary function of the endosperm, which usually develops before the embryo, is to:', options: ['Provide nutrition to the developing embryo', 'Form the seed coat', 'Produce pollen grains', 'Attract pollinators'], correctIndex: 0, explanation: 'The endosperm is a nutritive tissue that develops within the seed to nourish the developing embryo.', difficulty: 'easy' },
  { id: 'srfp-147', type: 'mcq', question: 'In the most common type of endosperm development, the primary endosperm nucleus divides repeatedly without immediate wall (cell) formation; this pattern is called:', options: ['Helobial endosperm development', 'Cellular endosperm development', 'Nuclear endosperm development', 'Free megaspore development'], correctIndex: 2, explanation: 'In nuclear endosperm development, repeated free nuclear divisions occur without immediate cell wall formation, and this is the most common type.', difficulty: 'medium' },
  { id: 'srfp-148', type: 'mcq', question: 'The liquid endosperm present in a "tender" (young) coconut, commonly consumed as coconut water, is an example of endosperm that has remained in which state?', options: ['A completely lignified state', 'Completely absent state', 'Fully cellular state', 'Free-nuclear state'], correctIndex: 3, explanation: 'The liquid "coconut water" of a tender coconut is an example of free-nuclear endosperm, which becomes cellular (coconut flesh/meat) only later in development.', difficulty: 'medium' },
  { id: 'srfp-149', type: 'mcq', question: 'In the type of endosperm development in which cell wall formation occurs immediately after each division of the primary endosperm nucleus, this pattern is called:', options: ['Cellular endosperm development', 'Nuclear endosperm development', 'Helobial endosperm development', 'None of the above'], correctIndex: 0, explanation: 'In cellular endosperm development, cell wall formation follows immediately after every division of the PEN, as seen in plants like Balsam and Datura.', difficulty: 'medium' },
  { id: 'srfp-150', type: 'mcq', question: 'The type of endosperm development considered intermediate between the nuclear and cellular types, involving unequal division of the primary endosperm cell into micropylar and chalazal chambers, is called:', options: ['Perisperm development', 'Cellular endosperm development', 'Helobial endosperm development', 'Free nuclear development'], correctIndex: 2, explanation: 'Helobial endosperm development is an intermediate type in which the primary endosperm cell first divides unequally into a smaller chalazal and a larger micropylar chamber.', difficulty: 'hard' },
  { id: 'srfp-151', type: 'assertion-reason', question: 'Assertion (A): Endosperm development generally precedes embryo development in most angiosperm seeds.\nReason (R): The endosperm serves to nourish the developing embryo, so its early establishment ensures a ready food supply is available as the embryo begins to grow.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The nutritive role of the endosperm correctly explains why its development typically precedes and supports embryo development.', difficulty: 'medium' },
  { id: 'srfp-152', type: 'how-many', question: 'Consider the following statements about endosperm development:\n1. Nuclear endosperm development is the most common type in angiosperms.\n2. Cellular endosperm development involves cell wall formation immediately after each nuclear division.\n3. Helobial endosperm development is exactly the same as nuclear endosperm development.\n4. Coconut water represents a free-nuclear endosperm stage.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — helobial endosperm development is a distinct, intermediate type, not the same as nuclear development.', difficulty: 'hard' },

  // ============ EMBRYO DEVELOPMENT ============
  { id: 'srfp-154', type: 'mcq', question: 'The development of the embryo from the zygote is termed:', options: ['Apomixis', 'Embryogenesis', 'Gametogenesis', 'Sporogenesis'], correctIndex: 1, explanation: 'Embryogenesis refers to the process of embryo development from the zygote.', difficulty: 'easy' },
  { id: 'srfp-155', type: 'mcq', question: 'The zygote, formed after syngamy, is generally located at which position within the embryo sac?', options: ['The micropylar end', 'Outside the embryo sac altogether', 'Exactly at the centre of the embryo sac', 'The chalazal end'], correctIndex: 0, explanation: 'The zygote, formed within the embryo sac after fertilisation, is situated at the micropylar end.', difficulty: 'medium' },
  { id: 'srfp-156', type: 'mcq', question: 'Before undergoing further division, the zygote often synthesises new materials and increases in size; this stage is described as the zygote getting:', options: ['Dividing immediately without any preparation', 'Merged with the endosperm', 'Non-functional', 'Prepared for embryogenesis by developing a thick wall around itself'], correctIndex: 3, explanation: 'The zygote first prepares for embryogenesis by developing a wall around itself and, in many cases, undergoes a period of rest before dividing.', difficulty: 'medium' },
  { id: 'srfp-157', type: 'mcq', question: 'A typical dicotyledonous embryo consists of an embryonal axis and:', options: ['No cotyledons at all', 'Three cotyledons', 'One cotyledon (scutellum)', 'Two cotyledons'], correctIndex: 3, explanation: 'A typical dicot embryo has an embryonal axis and two cotyledons.', difficulty: 'easy' },
  { id: 'srfp-158', type: 'mcq', question: 'In a dicot embryo, the portion of the embryonal axis above the level of cotyledon attachment, which bears the plumule, is called the:', options: ['Coleorhiza', 'Radicle', 'Epicotyl', 'Hypocotyl'], correctIndex: 2, explanation: 'The epicotyl is the part of the embryonal axis above the level of cotyledon attachment; it terminates with the plumule (shoot apex).', difficulty: 'medium' },
  { id: 'srfp-159', type: 'mcq', question: 'The portion of the embryonal axis below the level of cotyledon attachment in a dicot embryo, terminating in the radicle, is called the:', options: ['Hypocotyl', 'Epicotyl', 'Coleoptile', 'Plumule'], correctIndex: 0, explanation: 'The hypocotyl is the region of the embryonal axis below the point of cotyledon attachment; it terminates in the radicle (root tip), which is covered by a root cap.', difficulty: 'medium' },
  { id: 'srfp-160', type: 'mcq', question: 'A typical monocotyledonous embryo has a single cotyledon; in the grass family (Poaceae), this single cotyledon is specifically called the:', options: ['Coleorhiza', 'Scutellum', 'Coleoptile', 'Aleurone layer'], correctIndex: 1, explanation: 'In grasses, the single cotyledon of the monocot embryo is called the scutellum.', difficulty: 'medium' },
  { id: 'srfp-161', type: 'mcq', question: 'In a grass (monocot) embryo, the sheath that covers the plumule (young shoot) is called the:', options: ['Scutellum', 'Coleorhiza', 'Testa', 'Coleoptile'], correctIndex: 3, explanation: 'The coleoptile is a protective sheath covering the plumule (young shoot) of the monocot embryo.', difficulty: 'medium' },
  { id: 'srfp-162', type: 'mcq', question: 'In a grass (monocot) embryo, the sheath that covers the radicle (young root) is called the:', options: ['Coleorhiza', 'Scutellum', 'Hypocotyl', 'Coleoptile'], correctIndex: 0, explanation: 'The coleorhiza is a protective sheath covering the radicle (young root) of the monocot embryo.', difficulty: 'medium' },
  { id: 'srfp-163', type: 'assertion-reason', question: 'Assertion (A): The dicot and monocot embryos differ mainly in the number of cotyledons.\nReason (R): A dicot embryo typically has two cotyledons, while a monocot embryo has a single cotyledon, often modified as a scutellum in grasses.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The difference in cotyledon number directly explains and supports the primary distinguishing feature stated in the assertion.', difficulty: 'medium' },
  { id: 'srfp-164', type: 'how-many', question: 'Consider the following statements about embryo development:\n1. The zygote is generally located at the micropylar end of the embryo sac.\n2. A typical dicot embryo has one cotyledon.\n3. The epicotyl lies above the level of cotyledon attachment and bears the plumule.\n4. The coleorhiza covers the plumule in a monocot embryo.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (a dicot embryo has two cotyledons), and statement 4 is wrong (the coleorhiza covers the radicle, not the plumule; the coleoptile covers the plumule).', difficulty: 'medium' },

  // ============ SEED STRUCTURE ============
  { id: 'srfp-166', type: 'mcq', question: 'A seed, formed from the fertilised ovule, essentially consists of:', options: ['Only the ovary wall', 'Only endosperm, without a seed coat', 'Only a seed coat, without any embryo', 'A seed coat and an embryo (with or without endosperm)'], correctIndex: 3, explanation: 'A seed consists of a seed coat and an embryo, and may also contain endosperm, depending on the species.', difficulty: 'easy' },
  { id: 'srfp-167', type: 'mcq', question: 'The two layers of the seed coat, developing from the integuments, are called the:', options: ['Perisperm (outer) and nucellus (inner)', 'Exine (outer) and intine (inner)', 'Epicarp (outer) and endocarp (inner)', 'Testa (outer) and tegmen (inner)'], correctIndex: 3, explanation: 'The seed coat has two layers derived from the integuments: the outer testa and the inner tegmen.', difficulty: 'medium' },
  { id: 'srfp-168', type: 'mcq', question: 'Seeds that retain part of the nucellus as a remnant, persistent nutritive tissue (as in black pepper and beet), are said to contain:', options: ['Endosperm', 'Perisperm', 'Cotyledon tissue', 'Pericarp'], correctIndex: 1, explanation: 'Perisperm is the remnant, persistent nucellus found in some seeds, such as black pepper and beet.', difficulty: 'medium' },
  { id: 'srfp-169', type: 'mcq', question: 'Seeds in which the endosperm remains as a food-storing tissue in the mature seed (e.g., wheat, maize, castor) are called:', options: ['Apomictic seeds', 'Albuminous seeds', 'Perispermic seeds only', 'Non-albuminous (exalbuminous) seeds'], correctIndex: 1, explanation: 'Albuminous (endospermic) seeds retain the endosperm as a food-storing tissue at maturity, e.g., wheat, maize, castor, sunflower.', difficulty: 'medium' },
  { id: 'srfp-170', type: 'mcq', question: 'Seeds in which the endosperm is completely used up during embryo development, with food stored instead in the cotyledons (e.g., pea, groundnut, gram), are called:', options: ['Albuminous seeds', 'Perispermic seeds', 'Non-albuminous (exalbuminous) seeds', 'Apomictic seeds'], correctIndex: 2, explanation: 'Non-albuminous (exalbuminous) seeds have their endosperm completely consumed, with the cotyledons taking over the food-storage function, as in pea and groundnut.', difficulty: 'medium' },
  { id: 'srfp-171', type: 'assertion-reason', question: 'Assertion (A): Both testa and tegmen of the seed coat originate from the ovule.\nReason (R): Testa and tegmen develop respectively from the outer and inner integuments of the ovule, following fertilisation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The development of testa and tegmen from the integuments of the ovule correctly explains why both seed coat layers originate from the ovule.', difficulty: 'medium' },
  { id: 'srfp-172', type: 'how-many', question: 'Consider the following statements about seed structure:\n1. Testa is the outer layer of the seed coat.\n2. Tegmen is derived from the outer integument.\n3. Perisperm represents the persistent remnant of nucellus tissue in certain seeds.\n4. Albuminous seeds retain endosperm at maturity, while exalbuminous seeds do not.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — the tegmen develops from the inner integument, not the outer one (testa develops from the outer integument).', difficulty: 'medium' },
  { id: 'srfp-173', type: 'how-many', question: 'Consider the following examples:\n1. Wheat\n2. Maize\n3. Pea\n4. Groundnut\n5. Castor\nHow many of the above are examples of non-albuminous (exalbuminous) seeds?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Pea and groundnut are exalbuminous (non-albuminous) seeds. Wheat, maize and castor are albuminous seeds that retain endosperm.', difficulty: 'medium' },
  { id: 'srfp-174', type: 'statement', question: 'Statement I: The micropyle of the ovule often persists as a small pore in the mature seed coat.\nStatement II: This persistent micropylar pore facilitates the entry of oxygen and water into the seed during germination.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains the functional significance mentioned in Statement I', 'Both statements are correct but unrelated', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The persistence of the micropyle (Statement I) directly enables its functional role in facilitating water/oxygen entry during germination (Statement II).', difficulty: 'medium' },

  // ============ FRUIT DEVELOPMENT, APOMIXIS AND POLYEMBRYONY ============
  { id: 'srfp-175', type: 'mcq', question: 'The ovary, after fertilisation, matures into the:', options: ['Seed coat', 'Embryo', 'Fruit', 'Endosperm'], correctIndex: 2, explanation: 'The ovary matures into a fruit after fertilisation, while the ovule(s) within it mature into seed(s).', difficulty: 'easy' },
  { id: 'srfp-176', type: 'mcq', question: 'The wall of the ovary, after fertilisation, develops into the fruit wall, called the:', options: ['Testa', 'Tegmen', 'Pericarp', 'Perisperm'], correctIndex: 2, explanation: 'The ovary wall develops into the pericarp, the wall of the fruit.', difficulty: 'easy' },
  { id: 'srfp-177', type: 'mcq', question: 'A fruit that develops from the ovary without fertilisation, generally lacking seeds, is called a:', options: ['True fruit', 'Parthenocarpic fruit', 'Composite fruit', 'Aggregate fruit'], correctIndex: 1, explanation: 'Parthenocarpic fruits develop without fertilisation and are generally seedless, e.g., banana.', difficulty: 'medium' },
  { id: 'srfp-178', type: 'mcq', question: 'Parthenocarpic fruit development can be induced artificially by the application of:', options: ['Cytokinins only, in isolation', 'Photosynthetic pigments', 'Antibiotics', 'Growth hormones'], correctIndex: 3, explanation: 'Parthenocarpic fruit development can be induced by applying growth hormones, even without fertilisation.', difficulty: 'medium' },
  { id: 'srfp-179', type: 'mcq', question: 'A form of asexual reproduction that mimics sexual reproduction, in which seeds are formed without the fusion of gametes, is called:', options: ['Vegetative propagation only', 'Autogamy', 'Xenogamy', 'Apomixis'], correctIndex: 3, explanation: 'Apomixis is a mechanism evolved to bypass fertilisation events for seed formation, producing seeds asexually while mimicking normal sexual reproduction.', difficulty: 'medium' },
  { id: 'srfp-180', type: 'mcq', question: 'Apomixis has become significantly important for the hybrid seed industry primarily because it can:', options: ['Only be used for producing sterile hybrid seeds', 'Prevent seed formation entirely', 'Help retain (fix) hybrid vigour indefinitely, since apomictically produced seeds do not undergo the segregation typical of sexual reproduction', 'Increase seed cost significantly with no other benefit'], correctIndex: 2, explanation: 'Apomixis allows fixation of hybrid vigour, since apomictically produced progeny (seeds) are genetically identical to the mother plant and avoid the segregation seen in normal sexual reproduction.', difficulty: 'hard' },
  { id: 'srfp-181', type: 'mcq', question: 'The occurrence of more than one embryo in a single seed is termed:', options: ['Apospory', 'Parthenocarpy', 'Dichogamy', 'Polyembryony'], correctIndex: 3, explanation: 'Polyembryony refers to the presence of more than one embryo in a single seed, observed commonly in citrus and mango.', difficulty: 'medium' },
  { id: 'srfp-182', type: 'mcq', question: 'In citrus and mango, polyembryony is commonly caused by the development of additional embryos from:', options: ['Multiple fertilisation events involving several eggs', 'The synergid cells only', 'The endosperm cells directly', 'Somatic cells of the nucellus surrounding the embryo sac (nucellar embryony)'], correctIndex: 3, explanation: 'In these plants, some nucellar cells surrounding the embryo sac develop into embryos, producing additional embryos through nucellar embryony, resulting in polyembryony.', difficulty: 'hard' },
  { id: 'srfp-183', type: 'assertion-reason', question: 'Assertion (A): Apomixis is of great interest to plant breeders, especially for fixing hybrid vigour in crop plants.\nReason (R): Apomictically produced seeds bypass normal meiosis and fertilisation, allowing offspring to be genetically identical to the parent, thus avoiding the loss of desirable hybrid traits seen in subsequent sexually reproduced generations.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The bypassing of meiosis/fertilisation and resulting genetic uniformity of apomictic offspring correctly explains why apomixis is valuable for fixing hybrid vigour.', difficulty: 'hard' },
  { id: 'srfp-184', type: 'assertion-reason', question: 'Assertion (A): Banana fruits are typically seedless.\nReason (R): Banana fruit development is usually parthenocarpic, occurring without fertilisation, so seeds do not form.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since banana fruit typically develops parthenocarpically (without fertilisation), the absence of seeds is correctly explained by this reproductive mode.', difficulty: 'medium' },
  { id: 'srfp-185', type: 'how-many', question: 'Consider the following statements about fruit and seed development:\n1. The ovary develops into the fruit, and the ovule develops into the seed.\n2. Parthenocarpic fruits typically contain fully developed seeds.\n3. Apomixis allows seed formation without the fusion of gametes.\n4. Polyembryony refers to the presence of multiple seeds within a single fruit.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (parthenocarpic fruits are generally seedless), and statement 4 is wrong (polyembryony refers to multiple embryos within a single seed, not multiple seeds).', difficulty: 'hard' },
  { id: 'srfp-186', type: 'how-many', question: 'Consider the following statements about apomixis and polyembryony:\n1. Apomixis is a form of asexual reproduction that mimics sexual reproduction.\n2. Apomixis is of particular interest for fixing hybrid vigour in seed-propagated crops.\n3. Polyembryony is commonly observed in citrus and mango.\n4. Nucellar embryony is a mechanism unrelated to polyembryony.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — nucellar embryony is a mechanism that directly leads to polyembryony in species like citrus and mango.', difficulty: 'medium' },
  { id: 'srfp-187', type: 'statement', question: 'Statement I: Parthenocarpic fruit development always requires fertilisation of the ovule to occur first.\nStatement II: Growth hormones can be used to artificially induce parthenocarpic fruit development in some crops.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — parthenocarpic fruit development specifically occurs without fertilisation. Statement II is correct.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'srfp-189', type: 'mcq', question: 'Which of the following correctly represents the sequence of events in sexual reproduction of flowering plants?', options: ['Fertilisation → Pollination → Gametogenesis → Seed formation', 'Gametogenesis → Pollination → Fertilisation → Post-fertilisation events (embryo, endosperm, seed, fruit)', 'Post-fertilisation events → Fertilisation → Pollination → Gametogenesis', 'Pollination → Gametogenesis → Post-fertilisation events → Fertilisation'], correctIndex: 1, explanation: 'The general sequence is gametogenesis (formation of male and female gametes), followed by pollination, fertilisation, and finally post-fertilisation events such as embryogenesis, endosperm development, and seed/fruit formation.', difficulty: 'medium' },
  { id: 'srfp-190', type: 'mcq', question: 'Which structure is common to both the male and female gametophyte development pathways, in the sense that both begin with a diploid mother cell that undergoes meiosis?', options: ['Pollen mother cell (microspore mother cell) and megaspore mother cell', 'Synergid and antipodal cell', 'Tapetum and nucellus', 'Egg cell and vegetative cell'], correctIndex: 0, explanation: 'Both the microspore mother cell (in the anther) and the megaspore mother cell (in the ovule) are diploid cells that undergo meiosis to initiate gametophyte development.', difficulty: 'medium' },
  { id: 'srfp-191', type: 'assertion-reason', question: 'Assertion (A): Flowering plants show significant investment in mechanisms that promote cross-pollination despite the seeming convenience of self-pollination.\nReason (R): Cross-pollination (xenogamy) generally results in greater genetic variation among offspring, which can be advantageous for adaptation and survival under changing environmental conditions.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The evolutionary advantage of greater genetic variation from cross-pollination correctly explains why plants have evolved multiple outbreeding devices, despite the relative convenience of self-pollination.', difficulty: 'medium' },
  { id: 'srfp-192', type: 'how-many', question: 'Consider the following statements summarising the chapter:\n1. Pollen grains represent the male gametophyte, and the embryo sac represents the female gametophyte.\n2. Double fertilisation, involving syngamy and triple fusion, is a defining feature of angiosperm reproduction.\n3. All angiosperm seeds necessarily retain endosperm at maturity.\n4. Apomixis and polyembryony are both examples of variations from typical sexual reproduction observed in flowering plants.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — many seeds are non-albuminous (exalbuminous), with the endosperm consumed before maturity.', difficulty: 'medium' },
  { id: 'srfp-193', type: 'how-many', question: 'Consider the following pairs:\n1. Microsporogenesis — occurs in the anther\n2. Megasporogenesis — occurs in the ovule\n3. Syngamy — fusion of male gamete with polar nuclei\n4. Triple fusion — fusion of male gamete with egg cell\nHow many of the above pairs are correctly matched?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Pairs 1 and 2 are correctly matched. Pairs 3 and 4 are swapped — syngamy is the fusion of a male gamete with the egg cell, and triple fusion is the fusion of a male gamete with the polar nuclei.', difficulty: 'medium' },
  { id: 'srfp-194', type: 'statement', question: 'Statement I: In flowering plants, both pre-fertilisation and post-fertilisation events are essential components of sexual reproduction.\nStatement II: Post-fertilisation events include the development of endosperm, embryo, seed and fruit.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements accurately summarise the overall structure of sexual reproduction in flowering plants, encompassing pre- and post-fertilisation stages.', difficulty: 'easy' },
  { id: 'srfp-195', type: 'assertion-reason', question: 'Assertion (A): The evolution of the pollen grain wall, with sporopollenin exine, has been advantageous for the survival and success of flowering plants.\nReason (R): Sporopollenin\'s remarkable resistance to heat, strong acids, alkalis and enzymatic degradation helps protect the pollen grain\'s genetic material during transport by wind, water or animal vectors.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The protective, highly resistant nature of sporopollenin correctly explains why it has been evolutionarily advantageous for successful pollen transport and survival.', difficulty: 'hard' },
  { id: 'srfp-196', type: 'mcq', question: 'Which of the following processes occurs entirely within the diploid sporophyte generation before the haploid gametophyte generation begins?', options: ['Formation of the egg apparatus', 'Formation of the pollen tube', 'Formation of the embryo sac', 'Meiosis in the pollen mother cell and megaspore mother cell'], correctIndex: 3, explanation: 'Meiosis in the pollen mother cell and megaspore mother cell occurs at the transition point, marking the end of diploid sporophytic tissue production and the beginning of the haploid gametophyte generation.', difficulty: 'hard' },
  { id: 'srfp-197', type: 'how-many', question: 'Consider the following statements about the male and female gametophyte generations:\n1. The pollen grain (male gametophyte) generally has fewer cells at maturity than the embryo sac (female gametophyte).\n2. Both gametophytes are haploid.\n3. The male gametophyte develops entirely outside the sporophyte plant body.\n4. The female gametophyte remains enclosed within the sporophytic tissue of the ovule throughout its development.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the male gametophyte (pollen grain) also develops initially within the sporophytic anther tissue before being released.', difficulty: 'hard' },
  { id: 'srfp-198', type: 'assertion-reason', question: 'Assertion (A): Fertilisation in flowering plants is entirely dependent on successful pollination.\nReason (R): Without pollen grains reaching the stigma and germinating to form a pollen tube, the male gametes cannot reach the egg cell and polar nuclei within the embryo sac for fertilisation to occur.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The necessity of pollen tube delivery of male gametes to the embryo sac correctly explains why fertilisation depends on prior successful pollination.', difficulty: 'medium' },
  { id: 'srfp-199', type: 'statement', question: 'Statement I: Self-incompatibility and dichogamy are both examples of mechanisms found within a single bisexual flower that reduce the chances of self-pollination.\nStatement II: Dicliny, unlike self-incompatibility and dichogamy, involves flowers that are entirely unisexual.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements are correct — self-incompatibility and dichogamy operate within bisexual flowers, while dicliny is based on the flower being entirely unisexual.', difficulty: 'medium' },
  { id: 'srfp-200', type: 'mcq', question: 'Overall, the chapter "Sexual Reproduction in Flowering Plants" primarily deals with which sequence of biological themes?', options: ['Flower structure, gametogenesis, pollination, fertilisation, and post-fertilisation development of seed and fruit', 'Only microbial applications in agriculture', 'Only classification of plant families', 'Only the anatomy of vegetative organs like root and stem'], correctIndex: 0, explanation: 'The chapter comprehensively covers flower structure, male and female gametophyte development, pollination, fertilisation and the post-fertilisation events leading to seed and fruit formation.', difficulty: 'easy' },
];

export default questions;
